#!/usr/bin/env bash
# Analista 101: dos tramos SOLO salientes desde Recepcion 100 a institucion.
# No altera Ventas, Recep-Ventas, PBX compartido, esquema SQL ni grabaciones.
set -euo pipefail
umask 077
python3 - "$@" <<'PY'
import os,sys,json,hashlib,tempfile,stat,shutil,subprocess
from pathlib import Path
SPECS=json.loads(r'''{"existing":[{"path":"app/services/TelefoniaGrabacionExpedienteTransferidaService.php","pairs":[[" */\ndeclare(strict_types=1);\nrequire_once __DIR__.'/../helpers/ZadarmaPbxIdentifierHelper.php';\nrequire_once __DIR__.'/TelefoniaPbxSegmentosService.php';\n\nclass TelefoniaGrabacionExpedienteTransferidaService\n{\n    private mysqli $db;"," */\ndeclare(strict_types=1);\nrequire_once __DIR__.'/../helpers/ZadarmaPbxIdentifierHelper.php';\nrequire_once __DIR__.'/TelefoniaPbxSegmentosService.php';\nrequire_once __DIR__.'/TelefoniaGrabacionesTransferenciaInstitucionService.php';\n\nclass TelefoniaGrabacionExpedienteTransferidaService\n{\n    private mysqli $db;"],["        if(!$assignment)return $reply('PARTICIPACION_PENDIENTE','Falta verificar la extensión que atendió esta llamada.');\n        $q=$this->db->prepare('SELECT evento,internal,received_at,call_id_with_rec,payload_json,is_recorded FROM telefonia_zadarma_eventos WHERE pbx_call_id=? ORDER BY id');\n        $q->bind_param('s',$pbx);$q->execute();$events=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();\n        $extension=(string)$assignment['extension'];\n        $proof=TelefoniaPbxSegmentosService::transferencia($events,$extension);\n        $arrival=(bool)array_filter($events,static fn($e)=>$e['evento']==='NOTIFY_INTERNAL'&&$e['internal']===$extension);\n        if((!$arrival&&$proof['origen']==='')||!$proof['atendida']||$proof['answer_at']<(string)$assignment['desde'])\n            return $reply('RESPUESTA_PENDIENTE','Falta el evento de respuesta de tu extensión; todavía no se habilita el audio.');","        if(!$assignment)return $reply('PARTICIPACION_PENDIENTE','Falta verificar la extensión que atendió esta llamada.');\n        $q=$this->db->prepare('SELECT evento,internal,received_at,call_id_with_rec,payload_json,is_recorded FROM telefonia_zadarma_eventos WHERE pbx_call_id=? ORDER BY id');\n        $q->bind_param('s',$pbx);$q->execute();$events=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();\n        $extension=(string)$assignment['extension'];\n        // Excepción EXCLUSIVA: salida 100 -> Analista 101 acreditada y\n        // vinculada al mismo expediente. El END del 100 no acredita el fin\n        // del 101, pero tampoco debe ocultar los dos NOTIFY_RECORD firmados.\n        if(str_starts_with($pbx,'out_')){\n            $institucion=new TelefoniaGrabacionesTransferenciaInstitucionService($this->db);\n            if($institucion->identidad($pbx,$usuarioId,$extension,$seguimientoId)){\n                try {\n                    $verified=$institucion->verificar($pbx,$usuarioId,$extension,$seguimientoId);\n                    if($verified['ids']){\n                        $r=$reply('REPORTADA',\n                            'Grabaciones reportadas para la transferencia institucional; disponibilidad al abrir.',\n                            $pbx,$verified['ids']);\n                        $r['tipo_audio']='INSTITUCION_SALIENTE';\n                        return $r;\n                    }\n                    return $reply('AUDIO_PENDIENTE','Aún no hay grabaciones reportadas para esta transferencia.');\n                }catch(DomainException $ignored){\n                    return $reply('PARTICIPACION_PENDIENTE',\n                        'Falta acreditar la respuesta de tu extensión en la transferencia.');\n                }\n            }\n        }\n        $proof=TelefoniaPbxSegmentosService::transferencia($events,$extension);\n        $arrival=(bool)array_filter($events,static fn($e)=>$e['evento']==='NOTIFY_INTERNAL'&&$e['internal']===$extension);\n        if((!$arrival&&$proof['origen']==='')||!$proof['atendida']||$proof['answer_at']<(string)$assignment['desde'])\n            return $reply('RESPUESTA_PENDIENTE','Falta el evento de respuesta de tu extensión; todavía no se habilita el audio.');"]]},{"path":"app/services/TelefoniaEntrantesAnalistaService.php","pairs":[["        $stmt->close();\n\n        $llamadas = [];\n        $operaciones=(new TelefoniaTransferenciaOperacionService($this->db))->delUsuario($usuarioId);\n        $consultas=[];\n        foreach($operaciones as $operacion)if((int)$operacion['destino_usuario']===$usuarioId && $operacion['modo']==='CONSULTADA')$consultas[$operacion['referencia']]=$operacion;\n        $clasificadorInterno = new TelefoniaAnalistaWebrtcService($this->db);\n        foreach ($ids as $id) {","        $stmt->close();\n\n        $llamadas = [];\n        $operaciones=(new TelefoniaTransferenciaOperacionService($this->db))->delUsuario($usuarioId);\n        // Sólo SALIENTES de Recepción transferidas a esta extensión para\n        // instituciones acreditadas: no depender del END del Analista.\n        require_once __DIR__.'/TelefoniaGrabacionesTransferenciaInstitucionService.php';\n        $grabacionesInstitucion=new TelefoniaGrabacionesTransferenciaInstitucionService($this->db);\n        $audiosSalidaRecepcion=[];\n        foreach($operaciones as $op){\n            $ref=(string)($op['referencia']??'');\n            if((int)($op['destino_usuario']??0)!==$usuarioId ||\n               (string)($op['destino_extension']??'')!==$extension ||\n               empty($op['entregada_at']) ||\n               !preg_match('/^out_[a-fA-F0-9]{32,64}$/D',$ref))continue;\n            try{\n                $v=$grabacionesInstitucion->verificar($ref,$usuarioId,$extension);\n                if($v['ids'])$audiosSalidaRecepcion[$ref]=true;\n            }catch(DomainException $ignored){ /* sin transferencia propia acreditada */ }\n        }\n        $consultas=[];\n        foreach($operaciones as $operacion)if((int)$operacion['destino_usuario']===$usuarioId && $operacion['modo']==='CONSULTADA')$consultas[$operacion['referencia']]=$operacion;\n        $clasificadorInterno = new TelefoniaAnalistaWebrtcService($this->db);\n        foreach ($ids as $id) {"],["                'pbx_conversacion_confirmada' => !empty($call['answer_at']) && self::segundosAtendidos($call)>0 && in_array($call['estado'] ?? '', ['ended','transferred'],true),\n                'clasificacion' => (string)($registro['estado'] ?? 'PENDIENTE'),\n                'seguimiento_id' => (int)($registro['seguimiento_id'] ?? 0),\n                'interaccion_id' => (int)($registro['interaccion_id'] ?? 0),\n                'grabacion_pbx_reportada' => !empty($call['answer_at']) &&\n                    in_array((string)($call['estado'] ?? ''), ['ended','transferred'], true) &&\n                    $this->eventos->buscarCallIdGrabacion($id) !== '',\n            ];\n        }\n        // Dos fuentes distintas: PBX firmada y observación de WebRTC local.\n        // La segunda siempre se identifica como NO verificada por PBX.","                'pbx_conversacion_confirmada' => !empty($call['answer_at']) && self::segundosAtendidos($call)>0 && in_array($call['estado'] ?? '', ['ended','transferred'],true),\n                'clasificacion' => (string)($registro['estado'] ?? 'PENDIENTE'),\n                'seguimiento_id' => (int)($registro['seguimiento_id'] ?? 0),\n                'interaccion_id' => (int)($registro['interaccion_id'] ?? 0),\n                'grabacion_institucion_transferida' => !empty($audiosSalidaRecepcion[$id]),\n                'grabacion_pbx_reportada' => !empty($audiosSalidaRecepcion[$id]) ||\n                    (!empty($call['answer_at']) &&\n                     in_array((string)($call['estado'] ?? ''), ['ended','transferred'], true) &&\n                     $this->eventos->buscarCallIdGrabacion($id) !== ''),\n            ];\n        }\n        // Dos fuentes distintas: PBX firmada y observación de WebRTC local.\n        // La segunda siempre se identifica como NO verificada por PBX."]]},{"path":"prueba_telefonia/api/llamadas_seguimiento.php","pairs":[["        'tiene_grabacion' => (bool)$puedeTenerGrabacion,\n        'grabacion_procesando' => (bool)$grabacionProcesando,\n        'grabacion_sin_vincular' => (bool)$grabacionSinVincular,\n        'grabacion_transferida_pbx' => $grabacionPbxId,\n        'estado_grabacion' => $evidenciaAudio['estado'],\n        'evidencia_grabacion_pendiente' => $evidenciaAudio['mensaje'],\n        'grabacion_url' => $puedeTenerGrabacion\n            ? 'prueba_telefonia/api/grabacion_interaccion.php?interaccion_id=' . $interaccionId","        'tiene_grabacion' => (bool)$puedeTenerGrabacion,\n        'grabacion_procesando' => (bool)$grabacionProcesando,\n        'grabacion_sin_vincular' => (bool)$grabacionSinVincular,\n        'grabacion_transferida_pbx' => $grabacionPbxId,\n        'grabacion_transferida_institucion' => ($evidenciaAudio['tipo_audio']??'')==='INSTITUCION_SALIENTE',\n        'seguimiento_id' => $seguimientoId,\n        'estado_grabacion' => $evidenciaAudio['estado'],\n        'evidencia_grabacion_pendiente' => $evidenciaAudio['mensaje'],\n        'grabacion_url' => $puedeTenerGrabacion\n            ? 'prueba_telefonia/api/grabacion_interaccion.php?interaccion_id=' . $interaccionId"]]},{"path":"public/javascript/seguimiento_llamadas_expediente.js","pairs":[["                            }\n                            button.disabled = true;\n                            errorBox.hidden = true;\n                            try {\n                                const url = new URL(\n                                    'prueba_telefonia/api/grabacion_transferida_pbx.php',\n                                    document.baseURI\n                                );\n                                url.searchParams.set('pbx_call_id', pbxVerificado);\n                                url.searchParams.set('verificar', '1');\n                                const response = await fetch(url.toString(), {\n                                    credentials: 'same-origin', cache: 'no-store'","                            }\n                            button.disabled = true;\n                            errorBox.hidden = true;\n                            try {\n                                const institucionSaliente=llamada.grabacion_transferida_institucion===true;\n                                const url = new URL(\n                                    institucionSaliente\n                                        ? 'prueba_telefonia/api/grabacion_transferida_institucion.php'\n                                        : 'prueba_telefonia/api/grabacion_transferida_pbx.php',\n                                    document.baseURI\n                                );\n                                if(institucionSaliente)url.searchParams.set('seguimiento_id',String(llamada.seguimiento_id||0));\n                                url.searchParams.set('pbx_call_id', pbxVerificado);\n                                url.searchParams.set('verificar', '1');\n                                const response = await fetch(url.toString(), {\n                                    credentials: 'same-origin', cache: 'no-store'"],["                                const info = await response.json();\n                                if (!info.ok || !info.disponible ||\n                                    !Number.isInteger(info.segmentos) || info.segmentos < 1 ||\n                                    !window.IMPE_TELEPHONY_SEGMENTS?.create(\n                                        host, url.toString(), info.segmentos\n                                    )) {\n                                    throw new Error('La grabación todavía no está disponible en Zadarma.');\n                                }\n                            } catch (error) {","                                const info = await response.json();\n                                if (!info.ok || !info.disponible ||\n                                    !Number.isInteger(info.segmentos) || info.segmentos < 1 ||\n                                    !window.IMPE_TELEPHONY_SEGMENTS?.create(\n                                        host, url.toString(), info.segmentos, info.segmentos_info||[]\n                                    )) {\n                                    throw new Error('La grabación todavía no está disponible en Zadarma.');\n                                }\n                            } catch (error) {"]]},{"path":"app/views/seguimiento_vinculacion/llamadas_entrantes.php","pairs":[["                    $vinculada = $situacion === 'VINCULADA';\n                    $sinIdentificar = $situacion === 'SIN_IDENTIFICAR';\n                    $seguimientoId = (int)($llamada['seguimiento_id'] ?? 0);\n                    $grabacionInterna = $esInterna && $esWebrtc && !empty($llamada['grabacion_disponible']);\n                    $audioPbx = !$esWebrtc && !$esInterna && !empty($llamada['contestada']) && !empty($llamada['grabacion_pbx_reportada']);\n                    $audioInternoUrl = $grabacionInterna\n                        ? BASE_URL . 'prueba_telefonia/api/grabacion_interna_analista.php?session_id=' . rawurlencode($pbxId)\n                        : '';\n                    $numero = trim((string)($llamada['numero'] ?? ''));","                    $vinculada = $situacion === 'VINCULADA';\n                    $sinIdentificar = $situacion === 'SIN_IDENTIFICAR';\n                    $seguimientoId = (int)($llamada['seguimiento_id'] ?? 0);\n                    $grabacionInterna = $esInterna && $esWebrtc && !empty($llamada['grabacion_disponible']);\n                    $audioInstitucionSaliente = !$esWebrtc && !$esInterna && !empty($llamada['grabacion_institucion_transferida']);\n                    $audioPbx = !$esWebrtc && !$esInterna && !empty($llamada['contestada']) &&\n                        (!empty($llamada['grabacion_pbx_reportada'])||$audioInstitucionSaliente);\n                    $audioInternoUrl = $grabacionInterna\n                        ? BASE_URL . 'prueba_telefonia/api/grabacion_interna_analista.php?session_id=' . rawurlencode($pbxId)\n                        : '';\n                    $numero = trim((string)($llamada['numero'] ?? ''));"],["                                    <?php elseif ($audioPbx): ?>\n                                        <button type=\"button\" class=\"linkage-call-audio-state is-available linkage-call-recording-toggle\"\n                                            data-incoming-pbx-toggle\n                                            data-pbx-id=\"<?= $esc($pbxId) ?>\"\n                                            aria-controls=\"<?= $esc($controlAudioId) ?>\" aria-expanded=\"false\">\n                                            <i class=\"bi bi-record-circle\" aria-hidden=\"true\"></i>\n                                            <span>Consultar grabación</span>\n                                            <i class=\"bi bi-chevron-down linkage-call-recording-chevron\" aria-hidden=\"true\"></i>\n                                        </button>\n                                    <?php elseif ($esInterna): ?>\n                                        <span class=\"linkage-call-result-badge is-verification-test\">Interna · no contabiliza</span>","                                    <?php elseif ($audioPbx): ?>\n                                        <button type=\"button\" class=\"linkage-call-audio-state is-available linkage-call-recording-toggle\"\n                                            data-incoming-pbx-toggle\n                                            data-pbx-id=\"<?= $esc($pbxId) ?>\"\n                                            data-pbx-salida-institucion=\"<?= $audioInstitucionSaliente?'1':'0' ?>\"\n                                            data-seguimiento-id=\"<?= $seguimientoId ?>\"\n                                            aria-controls=\"<?= $esc($controlAudioId) ?>\" aria-expanded=\"false\">\n                                            <i class=\"bi bi-record-circle\" aria-hidden=\"true\"></i>\n                                            <span><?= $audioInstitucionSaliente?'Consultar grabaciones':'Consultar grabación' ?></span>\n                                            <i class=\"bi bi-chevron-down linkage-call-recording-chevron\" aria-hidden=\"true\"></i>\n                                        </button>\n                                    <?php elseif ($esInterna): ?>\n                                        <span class=\"linkage-call-result-badge is-verification-test\">Interna · no contabiliza</span>"]]},{"path":"public/javascript/seguimiento_entrantes_analista.js","pairs":[["        const host = panel.querySelector('[data-incoming-pbx-audios]');\n        const heading=panel.querySelector('.linkage-call-inline-player-heading span');\n        heading.textContent='Verificando grabación…';error.hidden=true;host.replaceChildren();panel.hidden=false;\n        const pbx = button.dataset.pbxId || '';\n        const url = new URL('prueba_telefonia/api/grabacion_transferida_pbx.php', document.baseURI);\n        url.searchParams.set('pbx_call_id', pbx);\n        url.searchParams.set('verificar', '1');\n        button.disabled = true;\n        try {\n            const response = await fetch(url.toString(), {credentials:'same-origin', cache:'no-store'});","        const host = panel.querySelector('[data-incoming-pbx-audios]');\n        const heading=panel.querySelector('.linkage-call-inline-player-heading span');\n        heading.textContent='Verificando grabación…';error.hidden=true;host.replaceChildren();panel.hidden=false;\n        const pbx = button.dataset.pbxId || '';\n        const salidaInstitucion=button.dataset.pbxSalidaInstitucion==='1';\n        const url = new URL(salidaInstitucion\n            ? 'prueba_telefonia/api/grabacion_transferida_institucion.php'\n            : 'prueba_telefonia/api/grabacion_transferida_pbx.php', document.baseURI);\n        url.searchParams.set('pbx_call_id', pbx);\n        if(salidaInstitucion)url.searchParams.set('seguimiento_id',button.dataset.seguimientoId||'0');\n        url.searchParams.set('verificar', '1');\n        button.disabled = true;\n        try {\n            const response = await fetch(url.toString(), {credentials:'same-origin', cache:'no-store'});"]]}],"created":[{"path":"app/services/TelefoniaGrabacionesTransferenciaInstitucionService.php","content":"<?php\ndeclare(strict_types=1);\nrequire_once __DIR__.'/../helpers/ZadarmaPbxIdentifierHelper.php';\n\n/**\n * Sólo Analista: audios de una SALIENTE iniciada por Recepción, transferida\n * a su extensión y vinculada a una institución autorizada.\n *\n * Nunca requiere END del segundo tramo ni infiere autoría por teléfono/hora.\n * Las llamadas entrantes directas, individuales y Recepción -> Ventas no\n * utilizan esta clase.\n */\nfinal class TelefoniaGrabacionesTransferenciaInstitucionService\n{\n    public function __construct(private mysqli $db) {}\n\n    public function identidad(string $pbx,int $usuario,string $extension,int $seguimiento=0): ?array\n    {\n        if(!preg_match('/^out_[A-Fa-f0-9]{32,64}$/D',$pbx)||\n            !preg_match('/^[0-9]{3,6}$/D',$extension)||$usuario<=0)return null;\n        $q=$this->db->prepare(\"SELECT o.id,o.origen_extension,o.destino_extension,\n            o.destino_usuario,o.referencia,d.ruta_json\n            FROM telefonia_transferencia_operaciones o\n            INNER JOIN telefonia_disponibilidad d\n              ON d.referencia=BINARY o.referencia\n             AND d.origen_usuario=o.origen_usuario\n             AND d.destino_usuario=o.destino_usuario\n             AND d.origen_extension=BINARY o.origen_extension\n             AND d.destino_extension=BINARY o.destino_extension\n            WHERE o.referencia=BINARY ? AND o.destino_usuario=?\n              AND o.destino_extension=BINARY ? AND o.modo IN ('DIRECTA','CONSULTADA')\n              AND o.entregada_at IS NOT NULL\n            LIMIT 2\");\n        $q->bind_param('sis',$pbx,$usuario,$extension);\n        $q->execute();$rows=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();\n        if(count($rows)!==1)return null;\n        $op=$rows[0];$route=json_decode((string)($op['ruta_json']??''),true);\n        if(!is_array($route)||($route['tipo']??'')!=='INSTITUCION'||\n            (int)($route['responsable_id']??0)!==$usuario||\n            (string)($route['extension']??'')!==$extension||\n            (string)($route['referencia_llamada']??'')!==$pbx||\n            ($seguimiento>0&&(int)($route['seguimiento_id']??0)!==$seguimiento)||\n            (string)$op['origen_extension']===$extension)return null;\n        return ['pbx'=>$pbx,'origen'=>(string)$op['origen_extension'],\n            'destino'=>$extension,'seguimiento_id'=>(int)($route['seguimiento_id']??0)];\n    }\n\n    /** Prueba pura de eventos firmados: conservar 2 RECORD aunque falte END 101. */\n    public static function referencias(array $events,string $source,string $dest): array\n    {\n        if($source===$dest||!preg_match('/^[0-9]{3,6}$/D',$source)||\n            !preg_match('/^[0-9]{3,6}$/D',$dest))throw new DomainException('TRAMO_NO_ACREDITADO');\n        $started=false;$answered=false;$third=false;$ids=[];\n        foreach($events as $event){\n            $type=(string)($event['evento']??'');\n            $internal=trim((string)($event['internal']??''));\n            $payload=json_decode((string)($event['payload_json']??''),true)?:[];\n            $last=trim((string)($event['last_internal']??$payload['last_internal']??''));\n            foreach([$internal,$last] as $member){\n                if(preg_match('/^[0-9]{3,6}$/D',$member)&&\n                    $member!==$source&&$member!==$dest)$third=true;\n            }\n            if($type==='NOTIFY_OUT_START'&&$internal===$source)$started=true;\n            if($type==='NOTIFY_ANSWER'&&$internal===$dest&&$started)$answered=true;\n            if($type!=='NOTIFY_RECORD')continue;\n            $id=trim((string)($event['call_id_with_rec']??''));\n            if(ZadarmaPbxIdentifierHelper::callIdValido($id))$ids[$id]=true;\n        }\n        if(!$started||!$answered||$third||count($ids)>8)\n            throw new DomainException('TRAMO_NO_ACREDITADO');\n        return array_keys($ids);\n    }\n\n    public function eventos(string $pbx): array\n    {\n        $q=$this->db->prepare('SELECT evento,internal,call_id_with_rec,payload_json,received_at\n            FROM telefonia_zadarma_eventos WHERE pbx_call_id=BINARY ? ORDER BY id');\n        $q->bind_param('s',$pbx);$q->execute();\n        $events=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();\n        return $events;\n    }\n\n    public function verificar(string $pbx,int $usuario,string $extension,int $seguimiento=0): array\n    {\n        $op=$this->identidad($pbx,$usuario,$extension,$seguimiento);\n        if(!$op)throw new DomainException('TRAMO_NO_ACREDITADO');\n        $ids=self::referencias($this->eventos($pbx),$op['origen'],$op['destino']);\n        return ['op'=>$op,'ids'=>$ids];\n    }\n\n    public function resolver(string $pbx,int $usuario,string $extension,int $seguimiento,\n                             callable $record): array\n    {\n        $verified=$this->verificar($pbx,$usuario,$extension,$seguimiento);\n        $ids=$verified['ids'];$records=[];$segments=[];\n        foreach($ids as $i=>$id){\n            try {\n                $audio=$record($id);\n                $link=(string)($audio['link']??'');\n                if(!$link||!filter_var($link,FILTER_VALIDATE_URL)||\n                    !str_starts_with(strtolower($link),'https://'))continue;\n                $records[$i]=$audio;\n                $segments[]=['indice'=>$i,'tramo'=>$i+1,\n                    // NOTIFY_RECORD no certifica la extensión que produjo audio.\n                    'etiqueta'=>'Tramo PBX '.($i+1).' · extensión por verificar',\n                    'extension'=>'','segundos'=>null];\n            }catch(Throwable $ignored){}\n        }\n        return ['ok'=>true,'disponible'=>(bool)$records,'segmentos'=>count($records),\n            'segmentos_info'=>$segments,'estado'=>$records?\n                (count($records)===count($ids)?'DISPONIBLE':'DISPONIBLE_PARCIAL'):\n                ($ids?'GRABACION_EN_PREPARACION':'SIN_GRABACION_REPORTADA'),\n            'records'=>$records];\n    }\n}\n"},{"path":"prueba_telefonia/api/grabacion_transferida_institucion.php","content":"<?php\n/**\n * Analista: dos tramos de la SALIENTE Recepción -> Institución.\n * No altera grabacion_transferida_pbx.php, usada en las entrantes normales\n * y en los tramos de Recepción/Ventas.\n */\ndeclare(strict_types=1);\nsession_start();\n$root=dirname(__DIR__,2);\nrequire_once $root.'/config/db_connection.php';\nrequire_once $root.'/app/helpers/PermissionHelper.php';\nrequire_once $root.'/app/models/RolModel.php';\nrequire_once $root.'/app/services/ZadarmaRecordingService.php';\nrequire_once $root.'/app/services/TelefoniaGrabacionesTransferenciaInstitucionService.php';\nheader('Cache-Control: private, no-store');\nheader('X-Content-Type-Options: nosniff');\nif(($_SERVER['REQUEST_METHOD']??'')!=='GET'){http_response_code(405);exit;}\n$uid=(int)($_SESSION['usuario_id']??0);\nif($uid<=0){http_response_code(401);exit;}\n$roles=new RolModel();$roles->inicializarPermisosSistema();\n$_SESSION['permisos']=$roles->obtenerCodigosPermisosPorRol((int)($_SESSION['rol_id']??0));\nif(strcasecmp(trim((string)($_SESSION['rol']??'')),'Analista de Datos')!==0||\n   !tienePermiso('telefonia.usar')||!tienePermiso('telefonia.recibir')||\n   !tienePermiso('seguimientos_vinculacion.operar_propios')){\n    http_response_code(403);exit;\n}\n$pbx=trim((string)($_GET['pbx_call_id']??''));\n$seguimiento=filter_var($_GET['seguimiento_id']??'0',FILTER_VALIDATE_INT,\n    ['options'=>['min_range'=>0]]) ;\nif(!preg_match('/^out_[a-fA-F0-9]{32,64}$/D',$pbx)||$seguimiento===false){\n    http_response_code(422);exit;\n}\n$range=trim((string)($_SERVER['HTTP_RANGE']??''));\nif($range!==''&&!preg_match('/^bytes=\\d*-\\d*$/D',$range)){\n    http_response_code(416);exit;\n}\ntry{\n    $db=(new Database())->connect();\n    $q=$db->prepare(\"SELECT extension FROM telefonia_extensiones WHERE usuario_id=?\n      AND proveedor='ZADARMA' AND activo=1 AND permite_entrantes=1 LIMIT 1\");\n    $q->bind_param('i',$uid);$q->execute();$row=$q->get_result()->fetch_assoc();$q->close();\n    if(!$row)throw new DomainException('EXTENSION_NO_ACREDITADA');\n    $provider=new ZadarmaRecordingService(false);\n    $svc=new TelefoniaGrabacionesTransferenciaInstitucionService($db);\n    $result=$svc->resolver($pbx,$uid,(string)$row['extension'],(int)$seguimiento,\n        [$provider,'obtenerGrabacionPorCallId']);\n    if(isset($_GET['verificar'])){\n        unset($result['records']);\n        header('Content-Type: application/json; charset=utf-8');\n        echo json_encode($result,JSON_UNESCAPED_UNICODE);\n        exit;\n    }\n    $index=filter_var($_GET['segmento']??null,FILTER_VALIDATE_INT,\n        ['options'=>['min_range'=>0,'max_range'=>7]]);\n    if($index===null||$index===false||!isset($result['records'][$index])){\n        http_response_code(404);exit;\n    }\n    $audio=$provider->descargarGrabacion((string)$result['records'][$index]['link'],$range);\n    $body=(string)($audio['body']??'');\n    $type=strtolower(trim((string)($audio['content_type']??'')));\n    if($body===''||($type!==''&&!str_starts_with($type,'audio/')&&\n        $type!=='application/octet-stream')){http_response_code(502);exit;}\n    $mime=str_contains($type,'wav')?'audio/wav':\n        (str_contains($type,'ogg')?'audio/ogg':\n        (str_contains($type,'mp4')?'audio/mp4':'audio/mpeg'));\n    header('Content-Type: '.$mime);\n    header('Accept-Ranges: bytes');\n    if((string)($_GET['download']??'')==='1'){\n        $ext=$mime==='audio/wav'?'wav':($mime==='audio/ogg'?'ogg':\n            ($mime==='audio/mp4'?'m4a':'mp3'));\n        header('Content-Disposition: attachment; filename=\"transferencia-institucion-tramo-'\n            .($index+1).'.'.$ext.'\"');\n    }else header('Content-Disposition: inline');\n    $size=strlen($body);\n    $code=(int)($audio['status']??200);\n    $headers=is_array($audio['headers']??null)?$audio['headers']:[];\n    if($range!==''&&$code===206&&preg_match('~^bytes \\d+-\\d+/\\d+$~',\n            (string)($headers['content-range']??''))){\n        http_response_code(206);header('Content-Range: '.$headers['content-range']);\n    }elseif($range!==''){\n        // Un upstream sin Range se rebanará localmente; nunca devolver\n        // bytes incorrectos con Content-Range de una descarga completa.\n        preg_match('/^bytes=(\\d*)-(\\d*)$/',$range,$m);\n        $from=$m[1]??'';$to=$m[2]??'';\n        if(!$size||($from===''&&$to==='')){http_response_code(416);exit;}\n        if($from===''){\n            if((int)$to<=0){http_response_code(416);exit;}\n            $start=max(0,$size-(int)$to);$end=$size-1;\n        }else{\n            $start=(int)$from;$end=$to===''?$size-1:min((int)$to,$size-1);\n        }\n        if($start>=$size||$end<$start){http_response_code(416);exit;}\n        $body=substr($body,$start,$end-$start+1);\n        http_response_code(206);header('Content-Range: bytes '.$start.'-'.$end.'/'.$size);\n    }\n    header('Content-Length: '.strlen($body));\n    echo $body;\n}catch(DomainException $e){\n    http_response_code(403);\n    header('Content-Type: application/json; charset=utf-8');\n    echo json_encode(['ok'=>false,'estado'=>'ACCESO_NO_AUTORIZADO']);\n}catch(Throwable $e){\n    error_log('[grabacion_institucion_transferida] '.get_class($e));\n    http_response_code(502);\n    header('Content-Type: application/json; charset=utf-8');\n    echo json_encode(['ok'=>false,'estado'=>'ERROR_TEMPORAL']);\n}\n"}]}''')
def fail(message):
    sys.stderr.write('CONFLICTO: '+message+'\n')
    sys.exit(2)
if len(sys.argv)<2 or sys.argv[1] not in ('--check','--apply','--restore'):
    sys.stderr.write('Uso: IMPE_CRM_PUBLIC=/ruta/public_html bash script --check|--apply|--restore [respaldo]\n')
    sys.exit(1)
command=sys.argv[1]
crm_arg=os.environ.get('IMPE_CRM_PUBLIC','')
if not crm_arg:fail('Falta IMPE_CRM_PUBLIC.')
crm=Path(crm_arg).resolve()
if not (crm/'index.php').is_file():fail('La carpeta no es la raiz del CRM.')
backups=Path(os.environ.get('IMPE_CRM_BACKUPS',str(Path.home()/'impe-analista-audios-backups'))).resolve()
if backups==crm or backups in crm.parents or crm in backups.parents:
    fail('Los respaldos deben estar fuera de public_html.')
allpaths=[x['path'] for x in SPECS['existing']]+[x['path'] for x in SPECS['created']]
if len(allpaths)!=8 or len(set(allpaths))!=8:
    fail('Manifiesto inesperado.')
def sha(raw):return hashlib.sha256(raw).hexdigest()
def file_at(name,required=True):
    p=crm/name
    if p.is_symlink() or crm not in p.resolve().parents:
        fail('Ruta insegura: '+name)
    if required and not p.is_file():fail('Falta: '+name)
    if not required and p.exists() and not p.is_file():fail('No es archivo: '+name)
    return p
def atomic(path,raw,permissions):
    fd,tmp=tempfile.mkstemp(prefix='.impe-analista-audio-',dir=str(path.parent))
    try:
        os.fchmod(fd,permissions)
        with os.fdopen(fd,'wb') as f:
            f.write(raw);f.flush();os.fsync(f.fileno())
        os.replace(tmp,str(path))
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
def lint(path,raw):
    suffix='.php' if path.endswith('.php') else '.js'
    exe='php' if suffix=='.php' else 'node'
    if not shutil.which(exe):
        if exe=='php':fail('PHP requerido para validar sintaxis.')
        print('AVISO: node no instalado; JS se valida en CI.')
        return
    fd,temp=tempfile.mkstemp(suffix=suffix)
    try:
        with os.fdopen(fd,'wb') as stream:stream.write(raw)
        proc=subprocess.run([exe,'-l' if exe=='php' else '--check',temp],
                            stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        if proc.returncode:fail('Sintaxis incompatible en '+path+': '+(proc.stderr+proc.stdout).decode('utf8','replace')[-450:])
    finally:
        if os.path.exists(temp):os.unlink(temp)
if command=='--restore':
    if len(sys.argv)!=3:fail('Se requiere la ruta exacta del respaldo.')
    folder=Path(sys.argv[2]).resolve()
    if backups not in folder.parents or folder.is_symlink():fail('Respaldo no autorizado.')
    manifest=folder/'manifest.json'
    if not manifest.is_file():fail('Manifiesto ausente.')
    rows=json.loads(manifest.read_text(encoding='utf8'))
    if set(x['path'] for x in rows)!=set(allpaths):fail('Respaldo de otra entrega.')
    restore=[]
    for row in rows:
        path=file_at(row['path'],not row['created'])
        raw=path.read_bytes() if path.exists() else None
        if row['created']:
            if raw is not None and sha(raw)!=row['target_sha']:fail('Archivo nuevo modificado: '+row['path'])
            restore.append((path,None,row['mode'],raw is not None))
        else:
            original=(folder/row['backup']).read_bytes()
            if sha(original)!=row['original_sha']:fail('Respaldo alterado: '+row['path'])
            if raw is None or sha(raw) not in (row['target_sha'],row['original_sha']):fail('Archivo cambiado despues de publicar: '+row['path'])
            restore.append((path,original,row['mode'],sha(raw)==row['target_sha']))
    for path,raw,mode,needed in restore:
        if needed:
            if raw is None:path.unlink()
            else:atomic(path,raw,mode)
    print('OK: restauracion completa verificada; Ventas y BD intactos.')
    sys.exit(0)
if len(sys.argv)!=2:fail('Parametros imprevistos.')
plan=[]
for item in SPECS['existing']:
    path=file_at(item['path']);raw=path.read_bytes()
    try:content=raw.decode('utf8')
    except UnicodeDecodeError:fail('Archivo no UTF-8: '+item['path'])
    if b'\r\n' in raw and raw.count(b'\r\n')!=raw.count(b'\n'):
        fail('Archivo con CRLF mixto: '+item['path'])
    crlf=b'\r\n' in raw
    source=content.replace('\r\n','\n');changed=source;nold=0;nnew=0
    for before,after in item['pairs']:
        before=(before+'\n' if before.endswith('\r') else before).replace('\r\n','\n')
        after=(after+'\n' if after.endswith('\r') else after).replace('\r\n','\n')
        if source.count(before)==1 and source.count(after)==0:
            if changed.count(before)!=1:fail('Parches solapados: '+item['path'])
            changed=changed.replace(before,after,1);nold+=1
        elif source.count(before)==0 and source.count(after)==1:nnew+=1
        else:fail('Variante personalizada no reconocida: '+item['path'])
    if nold and nnew:fail('Publicacion parcial; no modificar: '+item['path'])
    target=(changed.replace('\n','\r\n') if crlf else changed).encode('utf8')
    if nold:lint(item['path'],target)
    plan.append(dict(path=item['path'],file=path,old=raw,target=target,mode=stat.S_IMODE(path.stat().st_mode),
                     created=False,state='pendiente' if nold else 'actualizado'))
for item in SPECS['created']:
    path=file_at(item['path'],False);target=item['content'].encode('utf8')
    existing=path.read_bytes() if path.exists() else None
    if existing is not None and existing!=target:
        fail('Archivo ya presente pero diferente: '+item['path'])
    if existing is None:lint(item['path'],target)
    plan.append(dict(path=item['path'],file=path,old=existing,target=target,
                    mode=stat.S_IMODE(path.stat().st_mode) if path.exists() else 0o644,
                    created=not path.exists(),state='pendiente' if existing is None else 'actualizado'))
for x in plan:print(x['path']+': '+x['state'])
pending=sum(x['state']=='pendiente' for x in plan)
print('Archivos a modificar:',pending)
if command=='--check':
    print('OK: verificacion de solo lectura, sin cambios.')
    sys.exit(0)
if not pending:
    print('OK: entrega instalada, sin cambios adicionales.')
    sys.exit(0)
backups.mkdir(parents=True,exist_ok=True,mode=0o700)
os.chmod(str(backups),0o700)
folder=Path(tempfile.mkdtemp(prefix='analista-audio-100-101-',dir=str(backups)))
os.chmod(str(folder),0o700)
manifest=[]
for i,x in enumerate(plan):
    name='%02d.bak'%i
    if x['old'] is not None:
        f=folder/name;f.write_bytes(x['old']);os.chmod(str(f),0o600)
    manifest.append(dict(path=x['path'],backup=name,created=x['created'],mode=x['mode'],
        original_sha=sha(x['old']) if x['old'] is not None else '',target_sha=sha(x['target'])))
mf=folder/'manifest.json'
mf.write_text(json.dumps(manifest,indent=2),encoding='utf8');os.chmod(str(mf),0o600)
finished=[]
try:
    for x in plan:
        if x['state']!='pendiente':continue
        current=x['file'].read_bytes() if x['file'].exists() else None
        if current!=x['old']:fail('Archivo editado concurrentemente: '+x['path'])
        atomic(x['file'],x['target'],x['mode']);finished.append(x)
except BaseException:
    for x in reversed(finished):
        current=x['file'].read_bytes() if x['file'].exists() else None
        if current is not None and sha(current)==sha(x['target']):
            if x['old'] is None:x['file'].unlink()
            else:atomic(x['file'],x['old'],x['mode'])
    raise
print('OK: grabaciones de Analista publicadas. Respaldo:',str(folder))
print('Sin cambios de BD, PBX, Reception/Ventas, su resultado ni su colgado.')
